const sentences = $('Make Script').first().json.sentences

// create one item per sentence
return sentences.map((sentence, index) => ({
  json: {
    index,
    sentence
  }
}));

const aligned = $items('Get Word Timing And Script')[0].json; 
const sentence = $json.sentence; 
const loopIndex = ($json.index !== undefined) ? Number($json.index) : $itemIndex;


// ---------- helpers ----------
const normalize = (str) =>
  String(str || '')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim()
    .replace(/\s+/g, ' ');

function buildFlatWords(segments) {
  const flat = [];
  (segments || []).forEach((seg, si) => {
    (seg.words || []).forEach((w, wi) => {
      if (w && w.start != null && w.end != null && typeof w.word === 'string') {
        flat.push({
          token: normalize(w.word),
          start: w.start,
          end: w.end,
          segIndex: si,
          wordIndex: wi,
        });
      }
    });
  });
  return flat;
}

function findSpanForSentence(sentence, flatWords, minRatio = 0.6) {
  const sentTokens = normalize(sentence).split(' ').filter(Boolean);
  if (!sentTokens.length || !flatWords.length) return null;

  const flatTokens = flatWords.map(w => w.token);
  let best = { len: 0, startIdx: -1, endIdx: -1 };

  for (let j = 0; j < flatTokens.length; j++) {
    if (flatTokens.length - j <= best.len) break;

    let k = 0;
    while (
      j + k < flatTokens.length &&
      k < sentTokens.length &&
      flatTokens[j + k] === sentTokens[k]
    ) {
      k++;
    }
    if (k > best.len) {
      best = { len: k, startIdx: j, endIdx: j + k - 1 };
      if (k === sentTokens.length) break; // perfect match
    }
  }

  const ratio = best.len / sentTokens.length;
  if (best.len > 0 && ratio >= minRatio) {
    const startTime = flatWords[best.startIdx].start;
    const endTime = flatWords[best.endIdx].end;
    return {
      startTime,
      endTime,
      totalTime: +(endTime - startTime).toFixed(3),
      matchRatio: +ratio.toFixed(3),
      matchedTokenCount: best.len,
    };
  }

  return null;
}

// ---------- main ----------
const flatWords = buildFlatWords(aligned.segments || []);
let span = findSpanForSentence(sentence, flatWords, 0.6);

// Fallback: segment-level containment if contiguous word match failed
if (!span) {
  const nSentence = normalize(sentence);
  const seg = (aligned.segments || []).find(s => normalize(s.text).includes(nSentence));
  if (seg) {
    span = {
      startTime: seg.start,
      endTime: seg.end,
      totalTime: +(seg.end - seg.start).toFixed(3),
      matchRatio: 0,
      matchedTokenCount: 0,
      note: 'segment fallback',
    };
  }
}

if (!span) {
  span = {
    startTime: null,
    endTime: null,
    totalTime: null,
    matchRatio: 0,
    matchedTokenCount: 0,
    note: 'No reliable match found',
  };
}

// ---------- return ----------
return [
  {
    json: {
      id: loopIndex + 1, // ✅ start IDs from 1
      sentence,
      ...span,
    },
  },
];

// Mode: Run Once For All Items
const items = $input.all();

// (optional) keep items ordered by id
items.sort((a, b) => (a.json.id ?? 0) - (b.json.id ?? 0));

// Align: each item's endTime = next item's startTime
for (let i = 0; i < items.length - 1; i++) {
  const cur  = items[i].json;
  const next = items[i + 1].json;

  if (next.startTime != null) {
    cur.endTime = next.startTime;              // enforce equality: end[i] = start[i+1]
  }

  // guard: if end < start, clamp end to start
  if (cur.endTime != null && cur.startTime != null && cur.endTime < cur.startTime) {
    cur.endTime = cur.startTime;
  }

  cur.totalTime = (cur.startTime != null && cur.endTime != null)
    ? +(cur.endTime - cur.startTime).toFixed(3)
    : null;

  cur.adjusted = true; // optional flag
}

// Handle the last item: keep its endTime as-is, then add +1s if present
const last = items[items.length - 1]?.json;
if (last) {
  // compute current totalTime first (if possible)
  last.totalTime = (last.startTime != null && last.endTime != null)
    ? +(last.endTime - last.startTime).toFixed(3)
    : null;

  // ➕ Add 1 second extra to the last item's endTime
  if (last.endTime != null) {
    last.endTime = +(last.endTime + 1).toFixed(3);
    if (last.startTime != null) {
      last.totalTime = +(last.endTime - last.startTime).toFixed(3);
    }
    last.extraSecondAdded = true; // optional flag
  }
}

return items;

return items.map(item => {
  const b = item.binary?.data;
  if (b) {
    b.fileName = (b.fileName && b.fileName.toLowerCase().endsWith('.mp4'))
      ? b.fileName
      : (b.fileName ? `${b.fileName}.mp4` : 'clip.mp4');
    b.mimeType = 'video/mp4';
  }
  return item;
});

// Code / Function node: combine current items
const clip_ids = items.map(i => i.json.clip_id).filter(Boolean);
if (!clip_ids.length) throw new Error('No clip_ids on input items');

return [{
  json: {
    clip_ids,
    transition_duration: 0.2,
    output_name: 'merged.mp4'
  }
}];

// 1. Get input item
 const item = $input.first().json;
 const languageKey = $('Start').first().json.language

 // 2. Parse the fullScriptWithoutSeperator string
 const fullScriptWithoutSeperator = JSON.parse(item.fullScriptWithoutSeperator || '{}');
 const fullScript = JSON.parse(item.fullScript || '{}');


 // 3. Extract English script
 const fullScriptEn = fullScriptWithoutSeperator[languageKey] || '';
 const scriptEn = fullScript[languageKey] || '';

 // 4. Split by '\u001f' if present
 const sentences = scriptEn.includes('\u001f')
   ? scriptEn.split('\u001f').filter(s => s.trim() !== '')
   : [scriptEn.trim()].filter(Boolean);



 return [{ "script":fullScriptEn, sentences }];
